extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var cave := find_by_name(main, "Cave") as CSGCombiner3D
	if not check("cave", cave != null, "Nella scena serve un nodo CSGCombiner3D chiamato Cave"):
		return
	check("cave_collision", cave.use_collision == true, "Il nodo Cave deve avere la proprietà use_collision attivata (true)")

	var rock := find_by_name(cave, "Rock") as CSGBox3D
	if check("rock", rock != null, "Cave deve contenere un figlio CSGBox3D chiamato Rock"):
		check("rock_size", rock.size == Vector3(8, 4, 8), "Rock deve avere dimensioni Vector3(8, 4, 8)")
		check("rock_pos", rock.position == Vector3(0, 2, -12), "Rock deve essere in posizione Vector3(0, 2, -12)")

	var hollow := find_by_name(cave, "Hollow") as CSGSphere3D
	if check("hollow", hollow != null, "Cave deve contenere un figlio CSGSphere3D chiamato Hollow"):
		check("hollow_op", hollow.operation == CSGShape3D.OPERATION_SUBTRACTION, "Hollow deve avere Operation impostata su Subtraction")
		check("hollow_radius", absf(hollow.radius - 2.5) < 0.1, "Hollow deve avere raggio 2.5")

	var entrance := find_by_name(cave, "Entrance") as CSGBox3D
	if check("entrance", entrance != null, "Cave deve contenere un figlio CSGBox3D chiamato Entrance"):
		check("entrance_op", entrance.operation == CSGShape3D.OPERATION_SUBTRACTION, "Entrance deve avere Operation impostata su Subtraction")
		check("entrance_size", entrance.size == Vector3(3, 3, 4), "Entrance deve avere dimensioni Vector3(3, 3, 4)")

